/**
 * Reads one sheet per variant and returns the variants ready for the product editor, with a per-row report. Nothing is written.
 * @summary Preview a product spec workbook
 */
export const postApiSpecSheetsImport = (
  postApiSpecSheetsImportBody: PostApiSpecSheetsImportBody,
  signal?: AbortSignal,
) => {
  const formData = new FormData();
  formData.append(`file`, postApiSpecSheetsImportBody.file);
  if (postApiSpecSheetsImportBody.template_id !== undefined) {
    formData.append(`template_id`, postApiSpecSheetsImportBody.template_id);
  }

  return orvalClient<SpecWorkbookPreview>({
    url: `/api/spec-sheets/import`,
    method: "POST",
    headers: { "Content-Type": "multipart/form-data" },
    data: formData,
    signal,
  });
};

